    ('f51f4a25-5161-5fe7-a044-27e4e584b816', '191569be-69c6-5fc4-beeb-b9fd92bb45c8', null, 1, $lynxpack${"title":"","objective":"Je compare et j’ordonne des nombres naturels jusqu’à 1 000.","teacherNote":"Fiche liée à la leçon 5 « Ordonner des nombres » de l’unité « Les nombres jusqu’à 1 000 ». Les nombres des questions sont les mêmes dans toutes les versions : seuls la langue et les appuis changent, et la version enrichie ajoute deux défis. La question 9 se corrige à la main.","instructions":"Lis chaque question attentivement. Pour comparer des nombres, compare d’abord les centaines, puis les dizaines, puis les unités.","text":"Rappel : en ordre croissant, on place les nombres du plus petit au plus grand. En ordre décroissant, on les place du plus grand au plus petit.","glossary":[{"term":"croissant","definition":"Qui va en augmentant : du plus petit au plus grand."},{"term":"décroissant","definition":"Qui va en diminuant : du plus grand au plus petit."},{"term":"la valeur de position","definition":"La valeur d’un chiffre selon sa place dans le nombre (unités, dizaines, centaines)."}],"questions":[{"id":"q1","kind":"ordering","prompt":"Place ces nombres en ordre croissant (du plus petit au plus grand).","hint":"","points":null,"category":"connaissance","items":[{"id":"a","text":"472"},{"id":"b","text":"247"},{"id":"c","text":"724"},{"id":"d","text":"427"}]},{"id":"q2","kind":"ordering","prompt":"Place ces nombres en ordre décroissant (du plus grand au plus petit).","hint":"","points":null,"category":"connaissance","items":[{"id":"a","text":"398"},{"id":"b","text":"93"},{"id":"c","text":"1 000"},{"id":"d","text":"389"},{"id":"e","text":"930"}]},{"id":"q3","kind":"multiple_choice","prompt":"Quel nombre se trouve entre 560 et 580?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"518"},{"id":"b","text":"575"},{"id":"c","text":"587"},{"id":"d","text":"650"}],"multipleAnswers":false},{"id":"q4","kind":"multiple_choice","prompt":"Coche tous les nombres plus grands que 609.","hint":"","points":null,"category":"habiletes","choices":[{"id":"a","text":"690"},{"id":"b","text":"596"},{"id":"c","text":"610"},{"id":"d","text":"609"},{"id":"e","text":"906"}],"multipleAnswers":true},{"id":"q5","kind":"true_false","prompt":"808 est plus petit que 880.","hint":"","points":null,"category":"connaissance"},{"id":"q6","kind":"short_answer","prompt":"Avec les cartes 5, 0 et 8, forme le plus grand nombre de trois chiffres possible. Utilise chaque carte une seule fois.","hint":"","points":null,"category":"application","lines":1},{"id":"q7","kind":"short_answer","prompt":"Avec les mêmes cartes, forme le plus petit nombre de trois chiffres possible.","hint":"","points":null,"category":"application","lines":1},{"id":"q8","kind":"ordering","prompt":"Trois équipes ont ramassé des canettes vides pour le recyclage : les Aigles en ont ramassé 346, les Loups 364 et les Castors 336. Place les équipes de celle qui en a ramassé le plus à celle qui en a ramassé le moins.","hint":"","points":null,"category":"application","items":[{"id":"a","text":"Les Aigles"},{"id":"b","text":"Les Loups"},{"id":"c","text":"Les Castors"}]},{"id":"q9","kind":"short_answer","prompt":"Yanis dit : « 99 est plus grand que 201, parce que 9 est plus grand que 2. » A-t-il raison? Explique ta réponse.","hint":"","points":null,"category":"communication","lines":3}],"visualSupports":["Un tableau de valeur de position (centaines, dizaines, unités) affiché au tableau.","Des cartes-nombres que les élèves peuvent déplacer pour les questions d’ordre.","Une droite numérique de 0 à 1 000, graduée par centaines, affichée au mur."]}$lynxpack$::jsonb),
    ('6531d2bf-c758-562b-ac80-8a63aa1b41a5', '191569be-69c6-5fc4-beeb-b9fd92bb45c8', r_level_1, 1, $lynxpack${"title":"","objective":"Je compare et j’ordonne des nombres naturels jusqu’à 1 000.","teacherNote":"Version Débutant : consignes courtes, exemples dans le rappel, indices et glossaire. Mêmes nombres que les autres versions. Lire les consignes avec les élèves au besoin.","instructions":"Lis chaque question. Compare les centaines. Ensuite, compare les dizaines. Ensuite, compare les unités.","text":"Rappel : ordre croissant = du plus petit au plus grand. Exemple : 2, 5, 9.\n\nOrdre décroissant = du plus grand au plus petit. Exemple : 9, 5, 2.","glossary":[{"term":"croissant","definition":"Du plus petit au plus grand."},{"term":"décroissant","definition":"Du plus grand au plus petit."},{"term":"une centaine","definition":"Un groupe de 100."},{"term":"une dizaine","definition":"Un groupe de 10."},{"term":"une unité","definition":"Un seul (1)."},{"term":"une carte","definition":"Un petit carton avec un chiffre dessus."}],"questions":[{"id":"q1","kind":"ordering","prompt":"Place les nombres du plus petit au plus grand.","hint":"Compare d’abord le chiffre des centaines.","points":null,"category":"connaissance","items":[{"id":"a","text":"472"},{"id":"b","text":"247"},{"id":"c","text":"724"},{"id":"d","text":"427"}]},{"id":"q2","kind":"ordering","prompt":"Place les nombres du plus grand au plus petit.","hint":"Compte d’abord les chiffres de chaque nombre.","points":null,"category":"connaissance","items":[{"id":"a","text":"398"},{"id":"b","text":"93"},{"id":"c","text":"1 000"},{"id":"d","text":"389"},{"id":"e","text":"930"}]},{"id":"q3","kind":"multiple_choice","prompt":"Quel nombre est entre 560 et 580?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"518"},{"id":"b","text":"575"},{"id":"c","text":"587"},{"id":"d","text":"650"}],"multipleAnswers":false},{"id":"q4","kind":"multiple_choice","prompt":"Coche tous les nombres plus grands que 