    ('3abd8869-be90-5f4f-8b82-d7a0ccfd5512', '191569be-69c6-5fc4-beeb-b9fd92bb45c8', r_level_4, 1, $lynxpack${"title":"","objective":"Je compare et j’ordonne des nombres naturels jusqu’à 1 000.","teacherNote":"Version Enrichi : vocabulaire mathématique plus précis (inférieur, supérieur, compris entre) et deux défis (questions 10 et 11). Mêmes nombres que les autres versions pour les questions 1 à 9.","instructions":"Lis chaque question attentivement. Pour comparer des nombres, examine d’abord le chiffre des centaines, puis celui des dizaines, puis celui des unités. Les deux dernières questions sont des défis.","text":"Rappel : en ordre croissant, on place les nombres du plus petit au plus grand (on peut utiliser le symbole <). En ordre décroissant, on les place du plus grand au plus petit (on peut utiliser le symbole >).","glossary":[{"term":"inférieur à","definition":"Plus petit que (symbole <)."},{"term":"supérieur à","definition":"Plus grand que (symbole >)."},{"term":"compris entre","definition":"Plus grand que le premier nombre et plus petit que le second."},{"term":"la valeur de position","definition":"La valeur d’un chiffre selon sa place dans le nombre (unités, dizaines, centaines)."}],"questions":[{"id":"q1","kind":"ordering","prompt":"Range ces nombres en ordre croissant.","hint":"","points":null,"category":"connaissance","items":[{"id":"a","text":"472"},{"id":"b","text":"247"},{"id":"c","text":"724"},{"id":"d","text":"427"}]},{"id":"q2","kind":"ordering","prompt":"Range ces nombres en ordre décroissant.","hint":"","points":null,"category":"connaissance","items":[{"id":"a","text":"398"},{"id":"b","text":"93"},{"id":"c","text":"1 000"},{"id":"d","text":"389"},{"id":"e","text":"930"}]},{"id":"q3","kind":"multiple_choice","prompt":"Lequel de ces nombres est compris entre 560 et 580?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"518"},{"id":"b","text":"575"},{"id":"c","text":"587"},{"id":"d","text":"650"}],"multipleAnswers":false},{"id":"q4","kind":"multiple_choice","prompt":"Coche tous les nombres supérieurs à 609.","hint":"","points":null,"category":"habiletes","choices":[{"id":"a","text":"690"},{"id":"b","text":"596"},{"id":"c","text":"610"},{"id":"d","text":"609"},{"id":"e","text":"906"}],"multipleAnswers":true},{"id":"q5","kind":"true_false","prompt":"808 est inférieur à 880.","hint":"","points":null,"category":"connaissance"},{"id":"q6","kind":"short_answer","prompt":"À l’aide des cartes 5, 0 et 8, utilisées chacune une seule fois, forme le plus grand nombre de trois chiffres possible.","hint":"","points":null,"category":"application","lines":1},{"id":"q7","kind":"short_answer","prompt":"Avec les mêmes cartes, forme maintenant le plus petit nombre de trois chiffres possible.","hint":"","points":null,"category":"application","lines":1},{"id":"q8","kind":"ordering","prompt":"Pour le recyclage, trois équipes ont ramassé des canettes vides : les Aigles en ont ramassé 346, les Loups 364 et les Castors 336. Classe les équipes en ordre décroissant selon le nombre de canettes ramassées.","hint":"","points":null,"category":"application","items":[{"id":"a","text":"Les Aigles"},{"id":"b","text":"Les Loups"},{"id":"c","text":"Les Castors"}]},{"id":"q9","kind":"short_answer","prompt":"Yanis affirme : « 99 est plus grand que 201, parce que 9 est plus grand que 2. » Son raisonnement est-il juste? Justifie ta réponse en parlant de la valeur de position.","hint":"","points":null,"category":"communication","lines":3},{"id":"q10","kind":"short_answer","prompt":"Défi : avec les cartes 3, 7, 0 et 1, forme tous les nombres de trois chiffres compris entre 300 et 400. Utilise chaque carte au plus une fois par nombre, puis écris ces nombres en ordre croissant.","hint":"","points":null,"category":"habiletes","lines":3},{"id":"q11","kind":"short_answer","prompt":"Défi : trouve le nombre compris entre 699 et 710 dont le chiffre des unités est 5.","hint":"","points":null,"category":"habiletes","lines":1}],"visualSupports":["Un tableau de valeur de position (centaines, dizaines, unités) affiché au tableau.","Des cartes-nombres que les élèves peuvent déplacer pour les questions d’ordre.","Une droite numérique de 0 à 1 000, graduée par centaines, affichée au mur."]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('f51f4a25-5161-5fe7-a044-27e4e584b816', $lynxpack${"answers":[{"questionId":"q1","kind":"ordering","orderedIds":["b","d","a","c"],"explanation":"247 < 427 < 472 < 724. On compare d’abord les centaines (2, 4, 4, 7), puis les dizaines pour 427 et 472."},{"questionId":"q2","kind":"ordering","orderedIds":["c","e","a","d","b"],"explanation":"1 000 > 930 > 398 > 389 > 93. Le nombre 93 n’a que deux chiffres : il est le plus petit."},{"questionId":"q3","kind":"multiple_choice","correctChoiceIds":["b"],"explanation":"560 < 575 < 580. Les nombres 518, 587 et 650 sont en dehors de l’intervalle."},{"questionId":"q4","kind":"multiple_choice","correctChoiceIds":["a","c","e"],"explanation":"690, 610 et 906 sont plus grands que 609. 596 est plus petit, et 609 est égal à 609."},{"questionId":"q5","kind":"true_false","correct":true,"explanation":"Vrai : les centaines sont égales (8), et 0 dizaine est moins que 8 dizaines."},{"questionId":"q6","kind":"short_answer","sampleAnswer":"850","acceptableAnswers":["850"],"explanation":"On place le plus grand chiffre aux centaines (8), puis le suivant aux dizaines (5)."},{"questionId":"q7","kind":"short_answer","sampleAnswer":"508","acceptableAnswers":["508"],"explanation":"058 n’est pas un nombre de trois chiffres. On place donc 5 aux centaines, puis 0 aux dizaines et 8 aux unités."},{"questionId":"q8","kind":"ordering","orderedIds":["b","a","c"],"explanation":"Les Loups (364) > les Aigles (346) > les Castors (336)."},{"questionId":"q9","kind":"short_answer","sampleAnswer":"Non. 201 a 2 centaines, alors que 99 n’a aucune centaine. 201 est donc plus grand que 99. Yanis a comparé des chiffres qui ne sont pas à la même position.","acceptableAnswers":[],"explanation":"Correction manuelle : la réponse doit dire non et parler des centaines (ou du nombre de chiffres)."}],"solution":""}$lynxpack$::jsonb),
