    ('89137093-cc81-5040-abe2-3a07524775fb', 'aa3a2e01-d417-5198-80e8-54ec675bb8c1', r_level_4, 1, $lynxpack${"title":"","objective":"J’estime, je compte et je représente la valeur de collections de pièces et de billets canadiens jusqu’à 100 $.","teacherNote":"Version au vocabulaire plus riche (valeur totale, montant, posséder) avec une explication plus poussée à la question 8. Les montants et les réponses sont les mêmes que dans la version de base.","instructions":"Lis attentivement chaque question. Quand on te demande d’expliquer, appuie ta réponse sur des calculs.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Coche toutes les collections qui valent exactement 10 $.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"deux billets de 5 $"},{"id":"b","text":"un billet de 5 $ et deux pièces de 2 $"},{"id":"c","text":"cinq pièces de 2 $"},{"id":"d","text":"un billet de 20 $"}],"multipleAnswers":true},{"id":"q2","kind":"short_answer","prompt":"Quelle est la valeur totale de cette collection : un billet de 20 $, un billet de 10 $, une pièce de 2 $ et trois pièces de 1 $?","hint":"","points":null,"category":"connaissance","lines":1},{"id":"q3","kind":"true_false","prompt":"Quatre pièces de 25 ¢ valent autant qu’une pièce de 1 $.","hint":"","points":null,"category":"connaissance"},{"id":"q4","kind":"matching","prompt":"Associe chaque collection à sa valeur. Une des valeurs est de trop.","hint":"","points":null,"category":"habiletes","left":[{"id":"l1","text":"3 billets de 20 $"},{"id":"l2","text":"1 billet de 50 $ et 1 billet de 5 $"},{"id":"l3","text":"7 billets de 10 $"},{"id":"l4","text":"2 billets de 20 $ et 3 pièces de 2 $"}],"right":[{"id":"ra","text":"46 $"},{"id":"rb","text":"70 $"},{"id":"rc","text":"60 $"},{"id":"rd","text":"64 $"},{"id":"re","text":"55 $"}]},{"id":"q5","kind":"ordering","prompt":"Place ces collections de celle qui vaut le moins à celle qui vaut le plus.","hint":"","points":null,"category":"habiletes","items":[{"id":"a","text":"4 billets de 5 $"},{"id":"b","text":"1 billet de 10 $ et 6 pièces de 2 $"},{"id":"c","text":"9 pièces de 2 $"},{"id":"d","text":"1 billet de 20 $ et 3 pièces de 1 $"}]},{"id":"q6","kind":"multiple_choice","prompt":"Jules possède un billet de 50 $, un billet de 20 $, un billet de 10 $ ainsi que quelques pièces dont la valeur totale est inférieure à 10 $. Quel montant estimes-tu qu’il possède?","hint":"","points":null,"category":"application","choices":[{"id":"a","text":"moins de 50 $"},{"id":"b","text":"entre 50 $ et 80 $"},{"id":"c","text":"entre 80 $ et 90 $"},{"id":"d","text":"plus de 100 $"}],"multipleAnswers":false},{"id":"q7","kind":"short_answer","prompt":"Représente un montant de 38 $ à l’aide du plus petit nombre possible de billets et de pièces. Nomme chaque billet et chaque pièce.","hint":"","points":null,"category":"application","lines":2},{"id":"q8","kind":"short_answer","prompt":"Yanis a 6 pièces de monnaie et Raphaëlle a 2 billets. Yanis affirme : « J’ai plus d’argent que toi, parce que j’ai plus d’objets. » Son raisonnement est-il toujours juste? Justifie ta réponse avec un exemple où il a raison et un exemple où il a tort.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('c3b4bf60-2775-5acd-b3fc-ab899be206e8', $lynxpack${"answers":[{"questionId":"q1","kind":"multiple_choice","correctChoiceIds":["a","c"],"explanation":"5 $ + 5 $ = 10 $ et 2 $ + 2 $ + 2 $ + 2 $ + 2 $ = 10 $. Un billet de 5 $ et deux pièces de 2 $ font 9 $, et le billet de 20 $ vaut plus que 10 $."},{"questionId":"q2","kind":"short_answer","sampleAnswer":"35 $","acceptableAnswers":["35 $","35$","35","35 dollars","trente-cinq dollars"],"explanation":"20 $ + 10 $ = 30 $; 30 $ + 2 $ = 32 $; 32 $ + 3 $ = 35 $."},{"questionId":"q3","kind":"true_false","correct":true,"explanation":"25 ¢ + 25 ¢ + 25 ¢ + 25 ¢ = 100 ¢, et 100 ¢ = 1 $."},{"questionId":"q4","kind":"matching","pairs":[{"leftId":"l1","rightId":"rc"},{"leftId":"l2","rightId":"re"},{"leftId":"l3","rightId":"rb"},{"leftId":"l4","rightId":"ra"}],"explanation":"3 × 20 $ = 60 $; 50 $ + 5 $ = 55 $; 7 × 10 $ = 70 $; 40 $ + 6 $ = 46 $. La valeur 64 $ n’est pas utilisée."},{"questionId":"q5","kind":"ordering","orderedIds":["c","a","b","d"],"explanation":"9 pièces de 2 $ = 18 $; 4 billets de 5 $ = 20 $; 10 $ + 12 $ = 22 $; 20 $ + 3 $ = 23 $."},{"questionId":"q6","kind":"multiple_choice","correctChoiceIds":["c"],"explanation":"Les billets valent 50 $ + 20 $ + 10 $ = 80 $. Les pièces ajoutent moins de 10 $ : Jules a donc entre 80 $ et 90 $."},{"questionId":"q7","kind":"short_answer","sampleAnswer":"Un billet de 20 $, un billet de 10 $, un billet de 5 $, une pièce de 2 $ et une pièce de 1 $ : 5 billets et pièces en tout.","acceptableAnswers":[],"explanation":"Correction manuelle : 20 $ + 10 $ + 5 $ + 2 $ + 1 $ = 38 $. Une collection qui vaut 38 $ avec plus de billets et de pièces montre que l’élève sait représenter le montant, mais la réponse complète n’en utilise que 5."},{"questionId":"q8","kind":"short_answer","sampleAnswer":"Non. Cela dépend de la valeur des pièces et des billets. Par exemple, 6 pièces de 1 $ font 6 $, mais 2 billets de 5 $ font 10 $ : Raphaëlle a alors plus d’argent que Yanis.","acceptableAnswers":[],"explanation":"Correction manuelle : la réponse doit dire non (ou « pas toujours ») et donner un exemple où les 2 billets valent plus que les 6 pièces."}],"solution":""}$lynxpack$::jsonb),
    ('31dbba05-e9e2-5f9c-a3bc-396b50bad092', $lynxpack${"answers":[{"questionId":"q1","kind":"multiple_choice","correctChoiceIds":["a","c"],"explanation":"5 $ + 5 $ = 10 $ et 2 $ + 2 $ + 2 $ + 2 $ + 2 $ = 10 $. Un billet de 5 $ et deux pièces de 2 $ font 9 $, et le billet de 20 $ vaut plus que 10 $."},{"questionId":"q2","kind":"short_answer","sampleAnswer":"35 $","acceptableAnswers":["35 $","35$","35","35 dollars","trente-cinq dollars"],"explanation":"20 $ + 10 $ = 30 $; 30 $ + 2 $ = 32 $; 32 $ + 3 $ = 35 $."},{"questionId":"q3","kind":"true_false","correct":true,"explanation":"25 ¢ + 25 ¢ + 25 ¢ + 25 ¢ = 100 ¢, et 100 ¢ = 1 $."},{"questionId":"q4","kind":"matching","pairs":[{"leftId":"l1","rightId":"rc"},{"leftId":"l2","rightId":"re"},{"leftId":"l3","rightId":"rb"},{"leftId":"l4","rightId":"ra"}],"explanation":"3 × 20 $ = 60 $; 50 $ + 5 $ = 55 $; 7 × 10 $ = 70 $; 40 $ + 6 $ = 46 $. La valeur 64 $ n’est pas utilisée."},{"questionId":"q5","kind":"ordering","orderedIds":["c","a","b","d"],"explanation":"9 pièces de 2 $ = 18 $; 4 billets de 5 $ = 20 $; 10 $ + 12 $ = 22 $; 20 $ + 3 $ = 23 $."},{"questionId":"q6","kind":"multiple_choice","correctChoiceIds":["c"],"explanation":"Les billets valent 50 $ + 20 $ + 10 $ = 80 $. Les pièces ajoutent moins de 10 $ : Jules a donc entre 80 $ et 90 $."},{"questionId":"q7","kind":"short_answer","sampleAnswer":"Un billet de 20 $, un billet de 10 $, un billet de 5 $, une pièce de 2 $ et une pièce de 1 $ : 5 billets et pièces en tout.","acceptableAnswers":[],"explanation":"Correction manuelle : 20 $ + 10 $ + 5 $ + 2 $ + 1 $ = 38 $. Une collection qui vaut 38 $ avec plus de billets et de pièces montre que l’élève sait représenter le montant, mais la réponse complète n’en utilise que 5."},{"questionId":"q8","kind":"short_answer","sampleAnswer":"Non. Cela dépend de la valeur des pièces et des billets. Par exemple, 6 pièces de 1 $ font 6 $, mais 2 billets de 5 $ font 10 $ : Raphaëlle a alors plus d’argent que Yanis.","acceptableAnswers":[],"explanation":"Correction manuelle : la réponse doit dire non (ou « pas toujours ») et donner un exemple où les 2 billets valent plus que les 6 pièces."}],"solution":""}$lynxpack$::jsonb),
