  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('5d280250-dd6a-51e3-9c32-c8838467fecd', 'afa54abb-94ae-5d52-bb32-207156abad95', null, 1, $lynxpack${"title":"","objective":"Je résous des équations qui contiennent une variable et je vérifie ma solution en remplaçant la variable par sa valeur.","teacherNote":"Billet de sortie pour la fin d’une leçon sur les équations. Les trois questions et les nombres sont les mêmes dans toutes les versions; seule la langue change. Si vous avez une balance à plateaux et des billes (ou des cubes), montrez la situation de la question 2 avant le billet : enlever 15 billes de chaque plateau garde l’équilibre. La question 3 se corrige à la main : on attend une vérification par substitution.","prompt":"Avant de partir, résous chaque équation et vérifie ta solution.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Quelle valeur de n rend l’équation 4 × n = 36 vraie?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"9"},{"id":"b","text":"32"},{"id":"c","text":"40"},{"id":"d","text":"144"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Sur une balance à plateaux, le plateau de gauche contient un sac fermé rempli de billes et 15 billes à côté. Le plateau de droite contient 42 billes. La balance est en équilibre, et le sac vide ne pèse presque rien. Écris une équation avec la lettre s pour le nombre de billes dans le sac, puis trouve la valeur de s.","hint":"","points":null,"category":"application","lines":3},{"id":"q3","kind":"short_answer","prompt":"Alix résout l’équation 72 ÷ n = 8. Elle trouve n = 64. Vérifie sa solution. A-t-elle raison? Explique.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('05ec3652-ec37-507a-8402-ef0a16d46f94', 'afa54abb-94ae-5d52-bb32-207156abad95', r_level_1, 1, $lynxpack${"title":"","objective":"Je résous des équations qui contiennent une variable et je vérifie ma solution en remplaçant la variable par sa valeur.","teacherNote":"Version Débutant : phrases courtes et un indice par question. Mêmes questions et mêmes nombres que les autres versions. Lisez les questions à voix haute au besoin et montrez une vraie balance si possible.","prompt":"Réponds aux 3 questions. Vérifie chaque réponse.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"4 × n = 36. Quelle est la valeur de n?","hint":"Quel nombre, multiplié par 4, donne 36?","points":null,"category":"connaissance","choices":[{"id":"a","text":"9"},{"id":"b","text":"32"},{"id":"c","text":"40"},{"id":"d","text":"144"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Une balance a deux plateaux. À gauche : un sac fermé avec des billes et 15 billes à côté. À droite : 42 billes. La balance est en équilibre : les deux côtés ont le même nombre de billes. Le sac vide ne pèse presque rien. Écris une équation avec la lettre s. La lettre s est le nombre de billes dans le sac. Ensuite, trouve s.","hint":"À gauche, il y a s + 15 billes. À droite, il y a 42 billes.","points":null,"category":"application","lines":3},{"id":"q3","kind":"short_answer","prompt":"Alix résout 72 ÷ n = 8. Elle trouve n = 64. Vérifie : remplace n par 64. A-t-elle raison? Écris oui ou non. Explique.","hint":"Calcule 72 ÷ 64. Est-ce que cela donne 8?","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('6d269e6a-130b-5492-9e9c-6f5bb6ba3021', 'afa54abb-94ae-5d52-bb32-207156abad95', r_level_2, 1, $lynxpack${"title":"","objective":"Je résous des équations qui contiennent une variable et je vérifie ma solution en remplaçant la variable par sa valeur.","teacherNote":"Version Intermédiaire : phrases simples, une précision sur l’équilibre et une consigne de vérification guidée à la question 3. Mêmes questions et mêmes nombres que les autres versions.","prompt":"Avant de partir, résous les équations. Vérifie chaque solution.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Quelle valeur de n rend l’équation 4 × n = 36 vraie?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"9"},{"id":"b","text":"32"},{"id":"c","text":"40"},{"id":"d","text":"144"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Sur une balance à plateaux, le plateau de gauche contient un sac fermé rempli de billes et 15 billes à côté. Le plateau de droite contient 42 billes. La balance est en équilibre : les deux plateaux ont le même nombre de billes. Le sac vide ne pèse presque rien. Écris une équation avec la lettre s pour le nombre de billes dans le sac, puis trouve la valeur de s.","hint":"Ce qui est à gauche est égal à ce qui est à droite.","points":null,"category":"application","lines":3},{"id":"q3","kind":"short_answer","prompt":"Alix résout l’équation 72 ÷ n = 8. Elle trouve n = 64. Vérifie sa solution en remplaçant n par 64. A-t-elle raison? Explique.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('5e5ef78f-65c0-571a-b5b3-f3a7e0c13565', 'afa54abb-94ae-5d52-bb32-207156abad95', r_level_3, 1, $lynxpack${"title":"","objective":"Je résous des équations qui contiennent une variable et je vérifie ma solution en remplaçant la variable par sa valeur.","teacherNote":"Version Avancé : même billet que la version de base, écrit dans le français attendu en 5e année.","prompt":"Avant de partir, résous chaque équation et vérifie ta solution.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Quelle valeur de n rend l’équation 4 × n = 36 vraie?","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"9"},{"id":"b","text":"32"},{"id":"c","text":"40"},{"id":"d","text":"144"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Sur une balance à plateaux, le plateau de gauche contient un sac fermé rempli de billes et 15 billes à côté. Le plateau de droite contient 42 billes. La balance est en équilibre, et le sac vide ne pèse presque rien. Écris une équation avec la lettre s pour le nombre de billes dans le sac, puis trouve la valeur de s.","hint":"","points":null,"category":"application","lines":3},{"id":"q3","kind":"short_answer","prompt":"Alix résout l’équation 72 ÷ n = 8. Elle trouve n = 64. Vérifie sa solution. A-t-elle raison? Explique.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb),
    ('4733fd0c-60a8-57f3-87d9-37a0f84efdbb', 'afa54abb-94ae-5d52-bb32-207156abad95', r_level_4, 1, $lynxpack${"title":"","objective":"Je résous des équations qui contiennent une variable et je vérifie ma solution en remplaçant la variable par sa valeur.","teacherNote":"Version Enrichi : vocabulaire plus précis (masse négligeable, traduire, substitution) et justification plus exigeante à la question 3. Mêmes questions et mêmes nombres que les autres versions.","prompt":"Avant de quitter la classe, résous chaque équation et démontre que ta solution est juste.","questions":[{"id":"q1","kind":"multiple_choice","prompt":"Détermine la valeur de n qui rend l’équation 4 × n = 36 vraie.","hint":"","points":null,"category":"connaissance","choices":[{"id":"a","text":"9"},{"id":"b","text":"32"},{"id":"c","text":"40"},{"id":"d","text":"144"}],"multipleAnswers":false},{"id":"q2","kind":"short_answer","prompt":"Une balance à plateaux est en équilibre. Sur le plateau de gauche : un sac fermé contenant un nombre inconnu de billes, et 15 billes. Sur le plateau de droite : 42 billes. On considère que le sac vide a une masse négligeable. Traduis la situation par une équation où s représente le nombre de billes du sac, puis résous-la.","hint":"","points":null,"category":"application","lines":3},{"id":"q3","kind":"short_answer","prompt":"Alix résout l’équation 72 ÷ n = 8 et obtient n = 64. Vérifie sa solution par substitution. Est-elle juste? Justifie ta réponse et, au besoin, corrige-la.","hint":"","points":null,"category":"communication","lines":3}]}$lynxpack$::jsonb);
  insert into public.library_item_answer_keys (version_id, answer_key) values
    ('5d280250-dd6a-51e3-9c32-c8838467fecd', $lynxpack${"answers":[{"questionId":"q1","kind":"multiple_choice","correctChoiceIds":["a"],"explanation":"4 × 9 = 36. Le choix 32 vient d’une soustraction (36 − 4), le choix 40 d’une addition (36 + 4) et le choix 144 d’une multiplication (36 × 4)."},{"questionId":"q2","kind":"short_answer","sampleAnswer":"s + 15 = 42 (ou 15 + s = 42). s = 27 : le sac contient 27 billes, car 27 + 15 = 42.","acceptableAnswers":["27","27 billes","s = 27","s=27"],"explanation":"Accepter toute lettre pour la variable. Pour garder l’équilibre, on peut enlever 15 billes de chaque plateau : il reste le sac d’un côté et 27 billes de l’autre. Erreur fréquente : additionner 42 et 15 (57)."},{"questionId":"q3","kind":"short_answer","sampleAnswer":"Non. Si je remplace n par 64, 72 ÷ 64 ne donne pas 8 (cela donne un peu plus que 1). La solution est n = 9, car 72 ÷ 9 = 8 (ou 8 × 9 = 72).","acceptableAnswers":[],"explanation":"Correction manuelle : la réponse doit remplacer n par 64 pour vérifier, dire que la solution est fausse et, si possible, trouver n = 9. Alix a soustrait 8 de 72 au lieu de chercher le diviseur."}],"solution":""}$lynxpack$::jsonb),
