  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('916d8fe9-325c-5942-9509-288c162fd1ee', 'd61cf6a7-1d24-541f-86a0-85073e463066', null, 1, $lynxpack${"title":"","objective":"Je chante en français avec fierté et je nomme ce qui fait vivre le français dans ma communauté.","teacherNote":"Paroles originales sur l’air de « Au clair de la lune », une mélodie traditionnelle française du domaine public. Chaque couplet a huit vers qui suivent les huit phrases de la mélodie (6, 5, 6, 5, 6, 5, 6 et 5 syllabes chantées). Chantez d’abord le refrain, puis ajoutez un couplet par jour. La chanson convient bien au 25 septembre, à une assemblée ou au début de la journée. Le couplet 3 reprend les symboles du drapeau franco-ontarien (le vert de l’été, le blanc de l’hiver, le lys et le trille). Après le couplet 2, demandez aux élèves où ils et elles entendent le français dans leur communauté, et d’où viennent les accents de la classe : toutes les réponses font partie de la chanson. Pour prolonger, la classe peut écrire un nouveau couplet sur un lieu de sa communauté, en gardant le rythme.","tune":"Au clair de la lune","verses":[{"label":"Couplet 1","lines":["Dans ma cour d’école,","On rit en français,","On joue, on se parle","Et on se connaît.","Dans le Nord, en ville,","Près des lacs, des champs,","Notre langue brille","Comme un feu de camp."]},{"label":"Refrain","lines":["En français, on chante,","En français, on vit,","Tous les accents dansent,","Ici, c’est chez nous!","Toutes nos histoires","Font un grand pays,","Chantons tous et toutes","En français d’ici!"]},{"label":"Couplet 2","lines":["Sur la patinoire,","Au parc, au marché,","Le français résonne","Comme une chanson.","Mes amies, mes amis","Viennent de partout,","Chaque voix raconte","Un bout de chez nous."]},{"label":"Refrain","lines":["En français, on chante,","En français, on vit,","Tous les accents dansent,","Ici, c’est chez nous!","Toutes nos histoires","Font un grand pays,","Chantons tous et toutes","En français d’ici!"]},{"label":"Couplet 3","lines":["Vert comme les feuilles","Des grands bois d’été,","Blanc comme la neige","Des longs mois d’hiver,","Le lys et le trille","Sur notre drapeau","Flottent dans la brise","Du matin au soir."]},{"label":"Refrain","lines":["En français, on chante,","En français, on vit,","Tous les accents dansent,","Ici, c’est chez nous!","Toutes nos histoires","Font un grand pays,","Chantons tous et toutes","En français d’ici!"]}],"gestures":["« En français, on chante » : les mains en porte-voix autour de la bouche.","« Tous les accents dansent » : on se balance doucement de gauche à droite.","« Ici, c’est chez nous! » : les deux mains sur le cœur.","« Font un grand pays » : les bras s’ouvrent bien grands.","« Comme un feu de camp » : les doigts bougent vers le haut, comme des flammes.","Couplet 3 : les bras ondulent au-dessus de la tête, comme un drapeau dans la brise."]}$lynxpack$::jsonb);
  perform app.library_refresh_search('d61cf6a7-1d24-541f-86a0-85073e463066');

