  insert into public.library_item_versions (id, item_id, language_level_id, schema_version, content) values
    ('1353d67f-da27-5db1-accf-4df59bb5d9cf', '78202143-3b58-5ddc-b3e2-e81208dffbab', null, 1, $lynxpack${"title":"","objective":"","teacherNote":"Banque de démonstration à valider en classe. Choisissez au plus un point fort et une prochaine étape par attente travaillée pendant l’étape, puis adaptez le texte à l’élève. Les entrées sont rédigées au neutre (épicène); {prénom} est remplacé par le prénom de l’élève, et « de {prénom} » devient « d’Éloïse » ou « de Bastien » selon le prénom. Les qualificatifs suivent la grille d’évaluation du rendement, comme les grilles d’évaluation de la bibliothèque (une compréhension limitée, partielle, générale ou approfondie; avec une efficacité limitée, avec une certaine efficacité, avec efficacité, avec beaucoup d’efficacité) : à vérifier contre le document officiel en vigueur.","scope":"subject","period":"term","entries":[{"kind":"strength","skill":null,"level":1,"progress":null,"rating":null,"category":"connaissance","expectationCodes":["B1.1"],"neutral":"Avec du soutien, {prénom} lit et représente des nombres jusqu’à 1 000 à l’aide de matériel de base dix et démontre une compréhension limitée de la valeur de position.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":2,"progress":null,"rating":null,"category":"connaissance","expectationCodes":["B1.1"],"neutral":"{prénom} lit et représente des nombres jusqu’à 1 000 de quelques façons et démontre une compréhension partielle de la valeur de position.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":3,"progress":null,"rating":null,"category":"connaissance","expectationCodes":["B1.1"],"neutral":"{prénom} lit, représente, compose et décompose des nombres jusqu’à 1 000 de différentes façons et démontre une compréhension générale de la valeur de position.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":4,"progress":null,"rating":null,"category":"connaissance","expectationCodes":["B1.1"],"neutral":"{prénom} compose et décompose des nombres jusqu’à 1 000 de multiples façons, choisit la représentation la plus utile et démontre une compréhension approfondie de la valeur de position.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":1,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.1"],"neutral":"{prénom} gagnerait à représenter un même nombre de deux façons, avec du matériel de base dix et par un dessin, en nommant les centaines, les dizaines et les unités.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":2,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.1"],"neutral":"Pour consolider ses apprentissages, {prénom} pourrait décomposer un nombre de plusieurs façons, par exemple 345 = 300 + 40 + 5 = 200 + 145.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":3,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.1"],"neutral":"{prénom} pourrait maintenant expliquer pourquoi deux décompositions différentes représentent le même nombre.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":4,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.1"],"neutral":"Il serait profitable que {prénom} invente des devinettes sur les nombres (« Je suis un nombre qui… ») et les présente à la classe.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":1,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.2"],"neutral":"{prénom} compare et ordonne des nombres jusqu’à 1 000 avec une efficacité limitée; une droite numérique l’aide à situer les nombres.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":2,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.2"],"neutral":"{prénom} compare et ordonne des nombres jusqu’à 1 000 avec une certaine efficacité, surtout lorsque les nombres ont autant de chiffres.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":3,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.2"],"neutral":"{prénom} compare et ordonne des nombres jusqu’à 1 000 avec efficacité en s’appuyant sur la valeur de position.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":4,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.2"],"neutral":"{prénom} compare et ordonne des nombres jusqu’à 1 000 avec beaucoup d’efficacité et justifie son raisonnement avec précision.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":1,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.2"],"neutral":"{prénom} gagnerait à comparer d’abord le chiffre des centaines, puis celui des dizaines, à l’aide d’un tableau de valeur de position.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":2,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.2"],"neutral":"Pour progresser, {prénom} pourrait s’exercer à ordonner des nombres qui n’ont pas autant de chiffres, comme 98, 405 et 450.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":3,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.2"],"neutral":"{prénom} pourrait maintenant utiliser les symboles <, > et = pour comparer des nombres dans des situations de la vie courante.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":4,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.2"],"neutral":"Il serait profitable que {prénom} crée des situations de comparaison pour la classe et explique la stratégie à suivre.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":1,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.3"],"neutral":"Avec de l’aide, {prénom} arrondit des nombres naturels à la dizaine près avec une efficacité limitée.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":2,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.3"],"neutral":"{prénom} arrondit des nombres naturels à la dizaine ou à la centaine près avec une certaine efficacité.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":3,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.3"],"neutral":"{prénom} arrondit des nombres naturels à la dizaine ou à la centaine près avec efficacité, dans divers contextes.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":4,"progress":null,"rating":null,"category":"application","expectationCodes":["B1.3"],"neutral":"{prénom} arrondit des nombres à la dizaine ou à la centaine près avec beaucoup d’efficacité et explique quand un arrondi est utile, par exemple pour estimer.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":1,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.3"],"neutral":"{prénom} gagnerait à situer un nombre entre deux dizaines sur une droite numérique avant de l’arrondir.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":2,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.3"],"neutral":"Pour progresser, {prénom} pourrait s’exercer à arrondir à la centaine près des nombres comme 250 ou 650, qui se trouvent à mi-chemin.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":3,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.3"],"neutral":"{prénom} pourrait maintenant choisir s’il vaut mieux arrondir à la dizaine ou à la centaine selon la situation.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":4,"progress":null,"rating":null,"category":null,"expectationCodes":["B1.3"],"neutral":"Il serait profitable que {prénom} utilise l’arrondi pour vérifier si ses réponses sont vraisemblables en résolution de problèmes.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":1,"progress":null,"rating":null,"category":"communication","expectationCodes":["B2.3"],"neutral":"{prénom} utilise une stratégie de calcul mental pour additionner de petits nombres et explique sa démarche avec une efficacité limitée.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":2,"progress":null,"rating":null,"category":"communication","expectationCodes":["B2.3"],"neutral":"{prénom} utilise quelques stratégies de calcul mental pour additionner et soustraire, et explique sa démarche avec une certaine efficacité.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":3,"progress":null,"rating":null,"category":"communication","expectationCodes":["B2.3"],"neutral":"{prénom} utilise diverses stratégies de calcul mental, dont l’estimation, pour additionner et soustraire, et explique sa démarche avec efficacité.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":4,"progress":null,"rating":null,"category":"communication","expectationCodes":["B2.3"],"neutral":"{prénom} choisit la stratégie de calcul mental la mieux adaptée aux nombres en jeu et explique sa démarche avec beaucoup d’efficacité.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":1,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.3"],"neutral":"{prénom} gagnerait à mémoriser les faits d’addition jusqu’à 20 pour faciliter le calcul mental.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":2,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.3"],"neutral":"Pour progresser, {prénom} pourrait décomposer les nombres en centaines, en dizaines et en unités pour calculer mentalement.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":3,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.3"],"neutral":"{prénom} pourrait maintenant comparer deux stratégies de calcul mental et dire laquelle convient le mieux à un calcul donné.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":4,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.3"],"neutral":"Il serait profitable que {prénom} présente ses stratégies de calcul mental à la classe et explique pourquoi elles fonctionnent.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":1,"progress":null,"rating":null,"category":"habiletes","expectationCodes":["B2.5"],"neutral":"Avec du soutien, {prénom} représente un problème d’addition à l’aide de matériel concret et le résout avec une efficacité limitée.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":2,"progress":null,"rating":null,"category":"habiletes","expectationCodes":["B2.5"],"neutral":"{prénom} représente et résout des problèmes d’addition et de soustraction à une étape avec une certaine efficacité.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":3,"progress":null,"rating":null,"category":"habiletes","expectationCodes":["B2.5"],"neutral":"{prénom} représente et résout des problèmes d’addition et de soustraction avec efficacité, à l’aide de divers outils et algorithmes.","feminine":"","masculine":""},{"kind":"strength","skill":null,"level":4,"progress":null,"rating":null,"category":"habiletes","expectationCodes":["B2.5"],"neutral":"{prénom} résout des problèmes d’addition et de soustraction à plusieurs étapes avec beaucoup d’efficacité et vérifie ses réponses.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":1,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.5"],"neutral":"{prénom} gagnerait à relire le problème et à souligner la question avant de choisir une opération.","feminine":"","masculine":""},{"kind":"next_step","skill":null,"level":2,"progress":null,"rating":null,"category":null,"expectationCodes":["B2.5"],"neutral":"Pour progresser, {prénom} pourrait représenter chaque problème par un dessin ou un modèle avant de calculer.","feminine":"","masculine":""},{"kind":"ne